UPDATE scheduler
SET args_query = 'SELECT (SELECT GROUP_CONCAT(TABLE_NAME SEPARATOR '','') FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_TYPE <> ''VIEW'' AND TABLE_NAME NOT LIKE ''cache_%'' AND TABLE_SCHEMA = DATABASE() AND TABLE_NAME NOT IN (SELECT SUBSTRING(TABLE_NAME, 2) FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_TYPE = ''VIEW'' AND TABLE_SCHEMA = DATABASE())) AS tables'
WHERE name = 'BACKUP_DATABASE';